sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	if (source.getValue('u_import_checkpoint')) {
		ignore = true;
		return;
	}

    var imp = new x_doppe_doppel_t_0.DoppelIOCImport();
    var entityContent;
    try {
        entityContent = imp.parseEntityContent(source.getValue('u_entity_content'));
    } catch (e) {
        log.error('Doppel onBefore: invalid entity_content JSON for staging row ' + source.getUniqueValue());
        ignore = true;
        return;
    }

    var alertId = source.u_alert_id ? source.u_alert_id.toString() : '';
    var product = source.u_product ? source.u_product.toString().toLowerCase() : '';
    var ingested = imp.isProductIngested(product);

	// Observable: only for products that are real IOCs (see ingest_products)
    var entity = source.u_entity ? source.u_entity.toString() : '';
    if (entity && ingested) {
        var obs = new GlideRecord('sn_ti_observable');
        obs.addQuery('value', entity);
		obs.setLimit(1);
        obs.query();
        var isNewObs = !obs.next();
        if (isNewObs) {
            obs.initialize();
            if (product == 'domains') {
				var category = new GlideRecord('sn_ti_observable_type_category');
				category.addQuery('name', 'URL');
				category.setLimit(2);
				category.query();

				if (!category.next() || category.hasNext()) {
					throw new Error('DoppelIOCImport: could not identify a unique URL observable category');
				}

				obs.setValue('type_category', category.getUniqueValue());
			}
            obs.setValue('value', entity);
            obs.setValue('finding', 'Suspicious');
        }

        // Root domain from entity_content (domains alerts only)
        var rootDomain = entityContent && entityContent.root_domain && entityContent.root_domain.domain ?
            String(entityContent.root_domain.domain) : '';

        var obsSysId = '';
        if (isNewObs) {
            obsSysId = obs.insert();
            if (!obsSysId) log.error('Doppel onBefore: could not insert observable for staging row ' + source.getUniqueValue());
        } else {
            obsSysId = obs.getUniqueValue();
        }

        // Doppel ownership (Observable Source row) + Doppel details row, latest alert wins
        if (obsSysId) {
            imp.recordDoppelObservable(obsSysId, {
                alert_id: alertId,
                brand: source.u_brand.toString(),
                product: product,
                platform: source.u_platform.toString(),
                queue_state: source.u_queue_state.toString(),
                entity_state: source.u_entity_state.toString(),
                last_activity: source.u_last_activity_timestamp.toString(),
                domain: rootDomain,
                doppel_link: source.u_doppel_link.toString(),
                audit_logs: source.u_audit_logs.toString(),        // latest 5 entries (JSON)
                screenshot_url: source.u_screenshot_url.toString() // signed link, valid ~1 h after import
            });
        }
    }

    // Indicator decision
    var decision = ingested
        ? imp.getIndicatorDecision(source.u_queue_state, source.u_entity_state, source.u_severity)
        : { action: 'exclude' };

    var hasIndicator = !!alertId && action === 'update';

    if (decision.action == 'promote') {
        target.active = true;
        target.revoked = false;
    } else if (hasIndicator && (decision.action == 'deactivate' || decision.action == 'exclude' || decision.action == 'none')) {
        target.active = false;
    } else if (hasIndicator && decision.action == 'revoke') {
        target.active = false;
        target.revoked = true;
    } else if (!hasIndicator) {
        ignore = true;
        return;
    }

    var created = source.u_created_at ? source.u_created_at.toString().substring(0, 10) : '';
    var lastAct = source.u_last_activity_timestamp ? source.u_last_activity_timestamp.toString().substring(0, 10) : '';
    if (created && !target.first_seen) target.first_seen = created;
    if (lastAct) target.last_seen = lastAct;

})(source, map, log, target);
